/* Editorial content comes exclusively from the backend; no local sample fallback. */
'use strict';
const exploreRoot='/admin-api/aigc/explore';
let exploreRows=[],exploreNext=null,exploreLoaded=false,exploreBusy=false,exploreError='',exploreSerial=0;
function exploreLocalized(value){const locale=window.StudioI18n?.getLocale()||'zh-CN';return value?.[locale]||value?.['zh-CN']||value?.en||value?.es||'';}
function exploreText(value){return `<span data-explore-i18n="${esc(JSON.stringify(value||{}))}" data-user-content>${esc(exploreLocalized(value))}</span>`;}
function exploreURL(path){if(!/^\/admin-api\/aigc\/explore\/[0-9]+\/media\/(cover|original)$/.test(path||''))return '';return (cloudConfig.apiBase||'')+path;}
function exploreCard(r){return `<article class="asset-card explore-card"><button class="asset-image" data-action="explore-preview" data-id="${r.id}" aria-label="预览作品"><img src="${esc(exploreURL(r.coverPath))}" alt="" loading="lazy">${r.mode!=='image'?`<span class="explore-kind">${({video:'视频',audio:'音频',music:'音乐'})[r.mode]}</span>`:''}</button><div class="asset-card-info"><h3>${exploreText(r.titles)}</h3><p class="explore-description">${exploreText(r.descriptions)}</p><div class="asset-btns"><button class="action-btn" data-action="explore-template" data-id="${r.id}">${icon('spark')}创作同款</button><button class="action-btn" data-action="explore-preview" data-id="${r.id}">查看详情</button></div></div></article>`;}
async function loadExplore(reset=true){if(!cloudConfig.cloudEnabled)return;const serial=++exploreSerial,filter=exploreFilter,offset=reset?0:exploreNext;if(offset==null)return;exploreBusy=true;exploreError='';if(reset){exploreRows=[];exploreNext=null;}if(page==='explore')renderExplore();try{const data=await cloudRequest(exploreRoot+'?mode='+encodeURIComponent(filter)+'&offset='+offset+'&limit=24');if(serial!==exploreSerial)return;exploreRows=reset?data.items:[...exploreRows,...data.items];exploreNext=data.nextOffset;exploreLoaded=true;}catch(error){if(serial===exploreSerial)exploreError=error.message;}finally{if(serial===exploreSerial){exploreBusy=false;if(page==='explore')renderExplore();}}}
let exploreLoadedFilter='all';
renderExplore=function(){if(exploreLoadedFilter!==exploreFilter){exploreLoadedFilter=exploreFilter;exploreSerial++;exploreBusy=false;exploreLoaded=false;exploreError='';exploreRows=[];exploreNext=null;}
 $('#view').innerHTML=header('每一个灵感，都值得发生','从别人的想象里，发现你的下一个故事。')+`<div class="filterbar"><div class="tabs">${[['all','为你推荐'],['image','灵感图片'],['video','动态世界'],['music','音乐'],['audio','音频']].map(([id,label])=>`<button class="tab ${exploreFilter===id?'active':''}" data-explore-filter="${id}">${label}</button>`).join('')}</div><button class="subtle-button" data-action="explore-refresh">刷新内容</button></div>${!cloudConfig.cloudEnabled?`<div class="empty"><h2>探索内容由后台配置</h2><p>请进入工作台查看已发布内容</p><a class="primary-btn" href="${esc(cloudConfig.studioUrl)}">进入工作台 ↗</a></div>`:exploreError?`<div class="empty"><h2>探索内容加载失败</h2><p data-user-content>${esc(exploreError)}</p><button class="secondary-btn" data-action="explore-refresh">重试</button></div>`:exploreRows.length?`<div class="gallery">${exploreRows.map(exploreCard).join('')}</div>`:`<div class="empty"><h2>${exploreBusy?'正在加载探索内容…':'暂无已发布内容'}</h2><p>${exploreBusy?'':'内容发布后会显示在这里'}</p></div>`}${exploreNext!=null?`<button class="secondary-btn explore-more" data-action="explore-more" ${exploreBusy?'disabled':''}>${exploreBusy?'正在加载…':'加载更多内容'}</button>`:''}`;
 if(!exploreLoaded&&!exploreBusy&&!exploreError&&cloudConfig.cloudEnabled)loadExplore();};
actions['explore-refresh']=()=>{exploreLoaded=false;loadExplore();};actions['explore-more']=()=>{if(!exploreBusy)loadExplore(false);};
actions['explore-preview']=cloudAction(async el=>{const r=await cloudRequest(exploreRoot+'/'+el.dataset.id);const src=esc(exploreURL(r.mediaPath));modal('探索作品',`<h3>${exploreText(r.titles)}</h3>${r.mode==='image'?`<img class="explore-preview-image" src="${src}" alt="">`:r.mode==='video'?`<video class="real-video-preview" controls poster="${esc(exploreURL(r.coverPath))}" src="${src}"></video>`:`<img class="explore-preview-cover" src="${esc(exploreURL(r.coverPath))}" alt=""><audio class="audio-preview" controls src="${src}"></audio>`}<p>${exploreText(r.descriptions)}</p><h3>创作提示词</h3><p class="detail-prompt" data-user-content>${esc(r.prompt)}</p>`,`<button class="primary-btn" data-action="explore-template" data-id="${r.id}">创作同款</button>${r.downloadEnabled?`<button class="secondary-btn" data-action="explore-download" data-id="${r.id}">下载原文件</button>`:''}`,true);});
actions['explore-download']=cloudAction(async el=>{const r=await cloudRequest(exploreRoot+'/'+el.dataset.id);if(!r.downloadEnabled)throw Error('此内容未开放下载');const response=await fetch(exploreURL(r.mediaPath),{cache:'no-store'});if(!response.ok)throw Error('素材暂不可用');const blob=await response.blob(),extension=({'image/png':'png','image/jpeg':'jpg','image/webp':'webp','video/mp4':'mp4','audio/mpeg':'mp3','audio/wav':'wav'})[blob.type]||'bin';previewBlob(blob,exploreLocalized(r.titles).replace(/[\\/:*?"<>|]/g,'').slice(0,80)+'.'+extension);});
actions['explore-template']=cloudAction(async el=>{if(!cloudRequire())return;const r=await cloudRequest(exploreRoot+'/'+el.dataset.id);await cloudFlush();closeModal();setMode(r.mode);const p=r.parameters||{},d=draft();for(const key of ['count','ratio','resolution','videoSeconds','musicSeconds','negativePrompt','voiceDesign','speed'])if(p[key]!==undefined)d[key]=p[key];d.prompt=r.prompt;d.refs=[];d.attachments=[];d.voiceId=undefined;const c=liveCapabilities(r.mode).find(c=>c.id===String(p.capabilityId))||liveCapabilities(r.mode)[0];if(c)selectCapability(c);save();navigate('create');syncComposer();$('#prompt').focus();toast('探索提示词和参数已载入，请确认后生成');});
if(cloudInitialRoute[0]==='explore-admin')page='explore';render();
